INSERT INTO [bioterio].[Funcionalidade] ([Nome], [Descricao]) VALUES (N'Animal', N'Módulo para gestão do plantel: cadastro de novos animais, edição de informações e fichas técnicas, além de visualização e busca na lista geral de animais cadastrados.');
INSERT INTO [bioterio].[Funcionalidade] ([Nome], [Descricao]) VALUES (N'Alimentação', N'Registro e controle da alimentação do animal, incluindo definição de dietas, porções, horários de trato, suplementos e histórico de consumo.');
INSERT INTO [bioterio].[Funcionalidade] ([Nome], [Descricao]) VALUES (N'Biometria', N'Registro, edição e monitoramento de medidas biométricas e peso dos animais, permitindo o acompanhamento do desenvolvimento do plantel.');
INSERT INTO [bioterio].[Funcionalidade] ([Nome], [Descricao]) VALUES (N'Atendimento veterinário', N'Realiza atendimentos veterinários, prescreve medicamentos e procedimentos, solicita exames, registra evolução clínica, alta ambulatorial e anexa arquivos.');
INSERT INTO [bioterio].[Funcionalidade] ([Nome], [Descricao]) VALUES (N'Espécies cadastradas', N'Registro, edição e consulta de todas as espécies que compõem o plantel, permitindo a organização e controle de dados taxonômicos no sistema.');
INSERT INTO [bioterio].[Funcionalidade] ([Nome], [Descricao]) VALUES (N'Desverminação', N'Registro do protocolo, dosagem realizada e monitoramento do controle parasitário e desverminação dos animais, incluindo histórico de aplicações e agendamento de reforços.');
INSERT INTO [bioterio].[Funcionalidade] ([Nome], [Descricao]) VALUES (N'Mapa de Execução', N'Painel de acompanhamento de medicações prescritas e agendadas.');
INSERT INTO [bioterio].[Funcionalidade] ([Nome], [Descricao]) VALUES (N'Registrar dose de medicação', N'Confirmação e registro de medicações prescritas, contendo dosagem aplicada, horário, responsável e observações da aplicação.');
INSERT INTO [bioterio].[Funcionalidade] ([Nome], [Descricao]) VALUES (N'Locais de origem cadastrados', N'Cadastro, alteração e consulta dos locais de procedência dos animais do plantel, garantindo a rastreabilidade de origem no SigBio.');
INSERT INTO [bioterio].[Funcionalidade] ([Nome], [Descricao]) VALUES (N'Rotinas', N'Permite cadastrar, editar e acompanhar tarefas e rotinas operacionais diárias das espécies, garantindo a padronização.');
INSERT INTO [bioterio].[Funcionalidade] ([Nome], [Descricao]) VALUES (N'Usuários', N'Cadastro e gerenciamento de usuários do sistema, incluindo vinculação de perfis.');
INSERT INTO [bioterio].[Funcionalidade] ([Nome], [Descricao]) VALUES (N'Gerenciamento de perfis', N'Cadastro e gerenciamento de perfis e papéis de acesso no ssitema.');
INSERT INTO [bioterio].[Funcionalidade] ([Nome], [Descricao]) VALUES (N'Modelo de documento', N'Templates de documentos.');
INSERT INTO [bioterio].[Funcionalidade] ([Nome], [Descricao]) VALUES (N'Medicações cadastradas', N'Nome popular e princípio ativo de uma medicação salva durante a prescrição.');
INSERT INTO [bioterio].[Funcionalidade] ([Nome], [Descricao]) VALUES (N'Instalações do biotério', N'Salas e alojamentos dos animais no biotério');
